(() => {
'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',compass:'m16 8-3 5-5 3 3-5z M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',note:'M5 3h10l4 4v14H5z M9 11h6 M9 15h6 M14 3v5h5',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',external:'M14 3h7v7 M10 14 21 3 M10 5H4v16h16v-6',light:'M9 18h6 M10 21h4 M8 14a6 6 0 1 1 8 0l-1 2H9z',flag:'M5 22V3 M5 3c5-4 9 5 15 0v10c-6 5-10-4-15 0',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',close:'m6 6 12 12 M6 18 18 6',menu:'M4 6h16 M4 12h16 M4 18h16',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',spark:'m12 3 2 6 6 3-6 2-2 7-2-7-7-2 7-3z'};
const icon=(n,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
const STEP_NAMES=['历史现场','先做预测','拆读原文','看懂方法','审查实验','形成判断','带走方法'];
const defaults=()=>({v:1,current:'attention',view:'course',papers:{},transfer:{},compassNotes:{}});
let state=defaults(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem('paperlab-v1')||'null');if(raw?.v===1&&raw.papers&&typeof raw.papers==='object'){state={...defaults(),...raw};if(!PAPERS.some(p=>p.id===state.current))state.current='attention';if(!['course','compass','journal','transfer'].includes(state.view))state.view='course';}}catch{storageOK=false;}
let statsMode='interval',pairedOverlap=65;
let menu=false,tab='table',chartCol=1,readTab='abstract',methodReveal=false,annotation=false,ablationReveal=false,statN=100,statK=60,scaleLog=true,toastTimer;
const paper=()=>PAPERS.find(p=>p.id===state.current)||PAPERS[0];
function progress(id=state.current){let p=state.papers[id];if(!p||typeof p!=='object')p=state.papers[id]={step:0,unlocked:0,choice:null,prediction:'',confidence:50,notes:'',quiz:null,experimentSeen:[],judgment:{},done:false};p.step=Math.max(0,Math.min(6,Number(p.step)||0));p.unlocked=Math.max(0,Math.min(6,Number(p.unlocked)||0));p.judgment=p.judgment||{};p.experimentSeen=p.experimentSeen||[];p.reading=p.reading||{current:0,answers:{}};p.reading.current=Math.max(0,Math.min(2,p.reading.current||0));p.reading.answers=p.reading.answers||{};p.evidence=Array.isArray(p.evidence)?p.evidence:[];p.probe=p.probe||{};if(p.predictionSaved&&!p.initialPrediction)p.initialPrediction={text:p.prediction,confidence:p.confidence};return p;}
function save(){try{localStorage.setItem('paperlab-v1',JSON.stringify(state));storageOK=true;}catch{storageOK=false;const el=$('.local-status');if(el)el.innerHTML='无法保存 · 请导出手记';}}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function resetTransient(){tab='table';chartCol=1;readTab='abstract';methodReveal=false;annotation=false;ablationReveal=false;}
function doneCount(){return PAPERS.filter(p=>state.papers[p.id]?.done).length;}
function sourceUrl(p=paper(),page=p.page){return `https://arxiv.org/pdf/${p.arxiv}#page=${page}`;}
function sourceBtn(page,label='打开原文',small=true){return `<button class="btn ${small?'small':''}" data-action="source" data-page="${page}">${icon('external',14)}${label}</button>`;}
function flow(nodes,kind=''){return `<div class="flow ${kind}">${nodes.map((n,i)=>`${i?'<span class="connector" aria-hidden="true"></span>':''}<div class="flow-node">${esc(n)}</div>`).join('')}</div>`;}
function header(){return `<header class="topbar"><button class="brand" data-action="view" data-view="course" aria-label="论文训练场首页"><span class="brandmark"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M7 4H3v16h4 M17 4h4v16h-4 M10 8l5 4-5 4"/></svg></span><span><span class="brandtitle">论文训练场</span><span class="brandsub">Paper Lab</span></span></button><button class="mobile-menu" data-action="menu" aria-expanded="${menu}">${icon('menu',16)}课程目录</button><nav class="topnav" aria-label="主导航"><button class="${['course','transfer'].includes(state.view)?'active':''}" data-action="view" data-view="course">阅读训练</button><button class="${state.view==='compass'?'active':''}" data-action="view" data-view="compass">阅读指南针</button><button class="${state.view==='journal'?'active':''}" data-action="view" data-view="journal">判断手记</button></nav><div class="local-status">${icon('check',14)}${storageOK?'进度保存在此浏览器':'保存不可用，请导出手记'}</div></header>`;}
function sidebar(){let groups={0:'基础：架构与规模',4:'转向：指令与工具',7:'前沿：行动与推理'};return `<aside class="sidebar ${menu?'open':''}" aria-label="课程目录"><div class="side-label"><span>学习路径</span><span>9 篇论文</span></div><div class="side-heading">从读懂，到独立判断</div><div class="progress-track"><div style="width:${doneCount()/9*100}%"></div></div><div class="progress-meta">${doneCount()} / 9 篇已形成判断</div>${PAPERS.map((p,i)=>`${groups[i]?`<div class="group-label">${groups[i]}</div>`:''}<button class="paper-link ${state.current===p.id&&state.view==='course'?'active':''}" data-action="paper" data-id="${p.id}" ${state.current===p.id&&state.view==='course'?'aria-current="page"':''}><span class="paper-index">${String(i+1).padStart(2,'0')}</span><span><span class="paper-name">${p.short}</span><span class="paper-meta" style="display:block">${p.year} · ${p.topic}</span></span>${state.papers[p.id]?.done?`<span class="paper-check" aria-label="已完成">${icon('check',14)}</span>`:''}</button>`).join('')}<div class="transfer-link"><button class="paper-link ${state.view==='transfer'?'active':''}" data-action="view" data-view="transfer"><span class="paper-index">${icon('flag',17)}</span><span><span class="paper-name">独立阅读挑战</span><span class="paper-meta" style="display:block">带上一篇没见过的论文</span></span></button></div><div class="side-bottom">不急着知道答案。<br>先留下一个属于你的问题。</div></aside>`;}
function rail(){const p=paper(),s=progress();const goals=['只识别当时的瓶颈','给自己的预测留一份记录','区分主张、证据与范围','找出真正变化的部分','分清结果与它的解释','写一条有边界的结论','把方法带到下一篇论文'];return `<aside class="rail" aria-label="阅读辅助"><div class="rail-card"><div class="rail-title">${icon('compass',17)}本轮练习</div><h3>${p.skill}</h3><p class="note">${goals[s.step]}。</p><ul class="rail-list"><li>${icon(s.predictionSaved?'check':'note',15)}<span>先留下预测</span></li><li>${icon(s.quiz===p.table.correct?'check':'eye',15)}<span>用原始证据检查直觉</span></li><li>${icon(s.done?'check':'flag',15)}<span>写出结论与保留意见</span></li></ul></div>${s.step<2?`<div class="rail-tip"><strong>${icon('light',16)} 暂时不揭晓</strong>此刻不需要知道作者的答案。你只需要想清楚：这个问题难在哪里？</div>`:`<div class="rail-card"><div class="rail-title">${icon('book',17)}回到证据</div><div class="rail-source">${esc(p.name)}</div><p>${p.authors}<br>arXiv:${p.arxiv}</p>${sourceBtn(s.step===4?p.table.page:1,'查看完整论文')}<p class="micro" style="margin-top:12px">英文摘录按原文呈现；中文批注是教学解释。表格节选保留出处与条件。</p></div>`}${s.step>=2?`<div class="rail-card"><div class="rail-title">${icon('note',17)}证据夹 <span class="notebook-count">${s.evidence.length}</span></div>${s.evidence.length?`<details><summary>查看已收集的证据</summary>${evidenceShelf()}</details>`:evidenceShelf()}</div><div class="rail-card"><div class="rail-title">${icon('book',17)}随用随查</div>${LEARNING[p.id].terms.map(k=>`<details class="term-detail"><summary>${esc(k)}</summary><strong>${esc(TERMS[k][0])}</strong><p>${esc(TERMS[k][1])}</p></details>`).join('')}</div>`:''}<div class="rail-card"><div class="rail-title">${icon('note',17)}随手记</div><label class="micro" for="quick-note">一个困惑，或一个待查证的点</label><textarea class="editable-note" id="quick-note" data-field="notes" placeholder="比如：这个 baseline 的预算一样吗？">${esc(s.notes)}</textarea><div class="field-meta"><span>自动保存在此浏览器</span></div></div>${s.step>=2?`<div class="rail-tip"><strong>把判断留给自己</strong>这里提供证据与自查问题，不为自由回答自动打分。理解要靠你给出的理由来检验。</div>`:''}</aside>`;}
function footer(hint,label,action,disabled=false){return `<footer class="lesson-footer"><div class="footer-hint">${hint}</div><button class="btn primary" data-action="${action}" ${disabled?'disabled':''}>${label}</button></footer>`;}
function stage0(p){return `<div class="lesson-body"><div class="step-label">${icon('clock',16)}第 1 步 / 先理解问题</div><div class="year-label">回到 ${p.year} 年</div><h2>${p.sceneTitle}</h2><p class="body-copy">${p.scene}</p><div class="diagram"><div class="diagram-label"><span>当时的一种常见路径</span><span>结构示意 · 非实验数据</span></div>${flow(p.old)}<div class="diagram-caption">先观察这条路径，瓶颈出现在哪一步？</div></div><div class="callout">${p.bottleneck}</div><p class="micro">${p.historical}</p></div>${footer('下一步，先预测你的解决方案。','进入预测','next')}`;}
function stage1(p,s){return `<div class="lesson-body"><div class="step-label">${icon('light',16)}第 2 步 / 先留下你的判断</div><h2>${p.question}</h2><p class="body-copy">选一个起点，再写下理由。预测不计对错，它会成为稍后对照证据的参照。</p><div class="options" role="group" aria-label="预测方案">${p.options.map((o,i)=>`<button class="option ${s.choice===i?'selected':''}" data-action="predict-option" data-index="${i}" aria-pressed="${s.choice===i}"><span class="option-marker">${String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join('')}</div><label class="field-label" for="prediction">${p.prompt}</label><textarea id="prediction" data-field="prediction" placeholder="我会尝试……因为……但如果……这个方案可能失败。">${esc(s.prediction)}</textarea><div class="field-meta"><span>至少 12 个字，留下可回看的理由</span><span id="prediction-count">${(s.prediction||'').trim().length} 字</span></div><label class="confidence" for="confidence"><span>目前有多大把握</span><input id="confidence" data-field="confidence" type="range" min="0" max="100" step="10" value="${s.confidence??50}"><output id="confidence-value">${s.confidence??50}%</output></label>${s.predictionSaved?'<div class="callout purple">这是你的预测记录。修改后点击下方按钮，会更新这份记录。</div>':''}</div>${footer('保存后才揭示作者的方案。','保存预测，开始读原文','save-prediction',s.choice===null||(s.prediction||'').trim().length<12)}`;}
function stage3(p,s){return `<div class="lesson-body"><div class="step-label">${icon('compass',16)}第 4 步 / 不把每个组件都当成创新</div><h2>真正改变的是哪一段？</h2><p class="body-copy">${p.method}</p><div class="diagram"><div class="diagram-label"><span>方法路径</span><span>教学重绘 · 不表示定量关系</span></div>${flow(p.flow,'method')}<div class="diagram-caption">沿着输入、处理、反馈和输出读一遍。</div></div><div class="prediction-replay"><div class="micro">你先前的预测 · 当时把握 ${s.initialPrediction?.confidence??s.confidence??50}%</div><p>${esc(s.initialPrediction?.text||s.prediction)}</p></div><h3 class="subheading">停一下：${p.methodQuestion}</h3><label class="screen-reader" for="method-note">你的方法解释</label><textarea id="method-note" data-field="methodNote" placeholder="先试着回答，再对照下面的解释。">${esc(s.methodNote)}</textarea><button class="btn text" data-action="method-reveal" aria-expanded="${methodReveal}">${icon('eye',15)}${methodReveal?'收起解释':'揭示解释'}</button>${methodReveal?`<div class="callout purple">${p.methodAnswer}</div><p class="micro">回看你的方案：${p.tradeoff}</p>`:''}</div>${footer('一个合理的方法，还需要实验来支持。','开始审查实验','next')}`;}
function tableHTML(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function quiz(p,s){const t=p.table,answered=s.quiz!==null&&s.quiz!==undefined;return `<h3 class="subheading">${t.quiz}</h3><div class="options" role="group" aria-label="实验判断题">${t.options.map((o,i)=>`<button class="option ${s.quiz===i?'selected':''}" data-action="quiz" data-index="${i}" aria-pressed="${s.quiz===i}"><span class="option-marker">${String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join('')}</div>${answered?`<div class="feedback ${s.quiz!==t.correct?'wrong':''}"><strong>${s.quiz===t.correct?'这个判断有证据支持。':'再检查一下比较条件。'}</strong><p>${t.explain}</p></div>`:''}`;}
function barChart(p){const t=p.table,col=chartCol,vals=t.rows.map(r=>r[col]),max=p.id==='scaling'?.1:100,metric=t.headers[col];return `<div class="chart"><div class="chart-controls"><span>${metric} · ${p.id==='scaling'?'指数':'百分比或 BLEU，依表头定义'}</span>${t.rows.every(r=>typeof r[2]==='number')?`<label>比较列 <select id="chart-column" aria-label="图表指标"><option value="1" ${col===1?'selected':''}>${t.headers[1]}</option><option value="2" ${col===2?'selected':''}>${t.headers[2]}</option></select></label>`:''}</div>${t.rows.map((r,i)=>`<div class="bar-row"><span>${esc(r[0])}</span><div class="bar-track"><div class="bar-fill" style="width:${Number(r[col])/max*100}%"></div>${p.id==='instruct'?`<span class="error-range" style="left:${Number(r[2].split('–')[0])}%;width:${Number(r[2].split('–')[1])-Number(r[2].split('–')[0])}%" aria-label="95% 置信区间 ${esc(r[2])}"></span>`:''}</div><span class="bar-value">${r[col]}</span></div>`).join('')}<div class="axis"><span>0</span><span>${max/2}</span><span>${max}</span></div><div class="diagram-caption">${p.id==='instruct'?'按原文重绘；横线是对应偏好率的 95% 置信区间。横轴从 0 起。':'按上方原表重绘；横轴从 0 起，无作者未报告的误差条。'}</div></div>`;}
function scalingPlot(){let points=Array.from({length:40},(_,i)=>{let n=10**(6+i/39*3),l=(8.8e13/n)**.076;let x=scaleLog?45+i/39*425:45+(n-1e6)/(1e9-1e6)*425;let y=scaleLog?190-(Math.log10(l)-.25)/.4*150:190-(l-1.8)/2.5*150;return `${x.toFixed(1)},${y.toFixed(1)}`;}).join(' ');return `<div class="chart"><div class="chart-controls"><span>L(N) = (8.8 × 10¹³ / N)^0.076</span><button class="btn small" data-action="scale">切换为${scaleLog?'线性':'双对数'}坐标</button></div><svg class="plot" viewBox="0 0 510 235" role="img" aria-label="教学公式的${scaleLog?'双对数':'线性'}曲线，不是作者原始测量点"><path d="M45 25V190H475" stroke="#a8aec1" fill="none"/><path d="M45 80H475 M45 135H475" stroke="#e5e7ef" fill="none"/><polyline points="${points}" stroke="#5146d9" stroke-width="3" fill="none"/><g fill="#6b7185" font-size="11"><text x="4" y="20">${scaleLog?'log L':'L'}</text><text x="42" y="210">10⁶</text><text x="440" y="210">10⁹ N</text><text x="210" y="231">${scaleLog?'双对数刻度':'线性刻度'}</text></g></svg><p class="micro">教学模拟：从作者报告的拟合公式计算，不是原始实验散点。对数变换能让幂律成为直线，但不会创造新的证据。</p></div>`;}
function stage4(p,s){const t=p.table;let inner='';if(tab==='table')inner=`<h2>${t.title}</h2><div class="micro">${t.metric}</div>${tableWithEvidence(p)}${comparisonHTML(p)}<div class="source-line"><span>${t.ref}</span>${sourceBtn(t.page,'核对原表')}</div><div class="callout orange">${t.note}</div><details><summary>为什么做这个实验？</summary><p>${t.why}</p></details><details><summary>为什么选这些 baseline？</summary><p>${t.baseline}</p></details>${quiz(p,s)}`;
if(tab==='chart')inner=`<h2>让图服务于比较，而不是制造印象。</h2><p class="body-copy">先读指标，再看坐标。注意：把同一张表画成图，不会增加一份独立证据。</p>${barChart(p)}${p.id==='scaling'?scalingPlot():''}<div class="callout purple">${p.id==='r1'?'切换两列，观察排名变化。横轴单位相同，但生成预算不同。':p.id==='react'?'切换 HotpotQA 与 FEVER。一个结论能否同时解释两列？':p.id==='gpt3'?'切换任务，观察 few-shot 的提升是否一样大。':p.id==='attention'?'切换语言对。不要因为看到最高的一根柱，就忽略 base 的表现。':'柱长可以表示效应大小，但没有误差条时，不要自行推断统计显著。'}</div>`;
if(tab==='ablation')inner=`<h2>去掉一个部件，究竟说明什么？</h2><p class="micro">${p.ablation.ref}</p>${p.ablation.rows.length?tableHTML(['设置',p.ablation.unit],p.ablation.rows):''}<h3 class="subheading">${p.ablation.question}</h3><label class="screen-reader" for="ablation-note">你的消融判断</label><textarea id="ablation-note" data-field="ablationNote" placeholder="这个对照支持……但同时可能改变了……">${esc(s.ablationNote)}</textarea><button class="btn text" data-action="ablation-reveal" aria-expanded="${ablationReveal}">${icon('eye',15)}${ablationReveal?'收起分析':'揭示边界分析'}</button>${ablationReveal?`<div class="callout purple">${p.ablation.answer}</div>`:''}`;
if(tab==='stats')inner=statsHTML();const all=s.experimentSeen.length===4;return `<div class="lesson-body"><div class="step-label">${icon('eye',16)}第 5 步 / 用真实数据检验直觉</div><div class="chip-tabs" role="group" aria-label="实验审查步骤">${[['table','读表'],['chart','读图'],['ablation','消融'],['stats','不确定性']].map(([k,n])=>`<button class="${tab===k?'active':''}" data-action="experiment-tab" data-tab="${k}" aria-pressed="${tab===k}">${s.experimentSeen.includes(k)?'✓ ':''}${n}</button>`).join('')}</div>${inner}</div>${footer(s.quiz!==t.correct?'先完成「读表」判断题。':!all?`再查看${[['chart','读图'],['ablation','消融'],['stats','不确定性']].filter(([k])=>!s.experimentSeen.includes(k)).map(x=>x[1]).join('、')}，然后形成判断。`:'分数、协议和边界都看过了。现在轮到你下结论。','写下我的判断','next',s.quiz!==t.correct||!all)}`;}
function judgmentReady(s){return ['claim','evidence','limit'].every(k=>(s.judgment[k]||'').trim().length>=12);}
function judgmentFields(s){return `<label class="field-label" for="judgment-claim">作者真正证明了什么？</label><textarea id="judgment-claim" data-judgment="claim" placeholder="在……任务和……设置下，相比……，观察到……">${esc(s.judgment.claim)}</textarea><label class="field-label" for="judgment-evidence">哪条证据支持它？</label><textarea id="judgment-evidence" data-judgment="evidence" placeholder="记录表号、对照、评估协议与关键数据。">${esc(s.judgment.evidence)}</textarea><label class="field-label" for="judgment-limit">没有证明什么？你还想补什么实验？</label><textarea id="judgment-limit" data-judgment="limit" placeholder="目前还不能排除……我会增加……对照。">${esc(s.judgment.limit)}</textarea><div class="field-meta"><span>每项至少 12 个字；长度只是提交条件，不代表内容正确。</span></div>`;}
function stage5(p,s){return `<div class="lesson-body"><div class="step-label">${icon('note',16)}第 6 步 / 你是这篇论文的审稿人</div><h2>写一条你愿意负责的结论。</h2><p class="body-copy">先独立写，再对照参考。结论不需要宏大，但每句话都应该有证据和边界。</p><details class="judgment-evidence"><summary>我的证据夹 · ${s.evidence.length} 条</summary>${evidenceShelf(true)}</details>${judgmentFields(s)}<div class="prediction-replay"><div class="micro">回看你的最初预测 · ${s.initialPrediction?.confidence??s.confidence??50}% 把握</div><p>${esc(s.initialPrediction?.text||s.prediction)}</p></div><label class="field-label" for="revision">读过证据后，你改变了什么看法？</label><textarea id="revision" data-field="revision" placeholder="我原先认为……现在更倾向于……因为……">${esc(s.revision)}</textarea>${s.judgmentSaved?reference(p):''}</div>${footer(s.judgmentSaved?'可继续修改；再次保存后进入复盘。':'先写下自己的版本，再解锁参考边界。',s.judgmentSaved?'保存判断，进入复盘':'保存判断，揭示参考','save-judgment',!judgmentReady(s))}`;}
function reference(p){return `<div class="subheading"><h3>对照参考：支持到哪一步，就说到哪一步。</h3><div class="evidence-line"><span>有证据</span><p>${p.proven}</p></div><div class="evidence-line"><span>未证明</span><p>${p.unproven}</p></div><div class="evidence-line"><span>后来</span><p>${p.later}</p></div><p class="micro">回看来源：<a href="${p.laterSource[1]}" target="_blank" rel="noopener noreferrer">${p.laterSource[0]} ${icon('external',12)}</a></p><div class="callout purple">这是一份边界参考，不是自动评分。若你的结论不同，请用原文证据保留你的判断。</div></div>`;}
function course(){const p=paper(),s=progress(),idx=PAPERS.indexOf(p);if(s.step===4&&!s.experimentSeen.includes(tab)){s.experimentSeen.push(tab);save();}return `<div class="breadcrumb"><div class="crumb-left">阅读训练 <span>/</span> ${String(idx+1).padStart(2,'0')} <span>/</span> ${p.topic}</div><span>按你的节奏阅读</span></div><div class="paperhead"><div><h1>${p.name}</h1><div class="paperhead-meta"><span>${p.authors}</span><span>${p.year}</span><span>${icon('clock',13)} 约 ${p.time} 分钟</span><span>原论文 + 交互训练</span></div></div><span class="tag">${p.skill}</span></div><nav class="steps" aria-label="本篇阅读步骤">${STEP_NAMES.map((n,i)=>`<button class="step ${s.step===i?'active':i<s.unlocked?'done':''}" data-action="step" data-step="${i}" ${i>s.unlocked?'disabled':''} ${s.step===i?'aria-current="step"':''}><span class="stepnum">${i<s.unlocked?icon('check',12):i+1}</span>${n}</button>`).join('')}</nav><div class="content-grid"><section class="lesson" aria-label="${STEP_NAMES[s.step]}">${[stage0,stage1,stage2,stage3,stage4,stage5,stage6][s.step](p,s)}</section>${rail()}</div><div class="page-footer">${icon('lock',12)}学习记录仅存此浏览器，可在「判断手记」导出。清除浏览器数据会删除记录。</div>`;}
function compass(){return `<div class="wide-page"><div class="page-top"><div><h1 class="page-title">阅读指南针</h1><p class="text-muted" style="margin:0;font-size:14px">遇到卡点时，找到一个值得继续问的问题。</p></div><button class="btn" data-action="view" data-view="course">回到当前论文</button></div><div class="skill-grid">${COMPASS.map(([name,body,q],i)=>`<article class="skill-card"><h3>${name}</h3><p>${body}</p><p class="question">${q}</p></article>`).join('')}</div></div>`;}
function journal(){const entries=PAPERS.filter(p=>state.papers[p.id]?.predictionSaved),t=state.transfer;return `<div class="wide-page"><div class="page-top"><div><h1 class="page-title">判断手记</h1><p class="text-muted" style="margin:0;font-size:14px">保留你曾经怎么想，以及证据让你改变了什么。</p></div><button class="btn" data-action="export">${icon('download',16)}导出 Markdown</button></div><div class="micro">已留下 ${entries.length} 份预测 · 已完成 ${doneCount()} 篇判断 · ${t.submitted?'1 份迁移自查':'尚未完成迁移挑战'}</div>${!entries.length?`<div class="empty">${icon('note',32)}<h3>第一份记录，从一个预测开始。</h3><p>读论文之前的想法也值得保存。这里会并排留下你的预测和最终判断。</p><button class="btn primary" data-action="view" data-view="course">回到训练</button></div>`:entries.map(p=>{let s=progress(p.id);return `<article class="journal-card"><div class="page-top" style="margin-bottom:10px"><h3 style="margin:0">${p.short} <span class="tag">${p.year}</span></h3><button class="btn small" data-action="paper" data-id="${p.id}">${s.done?'回看本篇':'继续训练'}</button></div><div class="journal-label">最初的预测 · 把握 ${s.initialPrediction?.confidence??s.confidence}%</div><div class="journal-text">${esc(s.initialPrediction?.text||s.prediction)}</div>${s.initialPrediction&&s.prediction!==s.initialPrediction.text?`<div class="journal-label">之后修改的预测</div><div class="journal-text">${esc(s.prediction)}</div>`:''}${s.judgmentSaved?`<div class="journal-label">我的结论</div><div class="journal-text">${esc(s.judgment.claim)}</div><div class="journal-label">证据</div><div class="journal-text">${esc(s.judgment.evidence)}</div><div class="journal-label">保留意见</div><div class="journal-text">${esc(s.judgment.limit)}</div>`:'<p class="micro" style="margin-top:15px">还没有形成判断，读完证据后再回来。</p>'}${s.revision?`<div class="journal-label">我改变的看法</div><div class="journal-text">${esc(s.revision)}</div>`:''}${s.probe.submitted?`<div class="journal-label">新情境首次判断 · ${s.probe.first?.confidence??50}% 把握</div><div class="journal-text">${esc(LEARNING[p.id].probe.options[s.probe.first?.choice??s.probe.choice])}</div><div class="journal-text">${esc(s.probe.first?.reason||s.probe.reason)}</div>${s.probe.choice!==LEARNING[p.id].probe.correct?'<p class="review-marker">这个判断值得回到新情境再检查。</p>':''}${s.probe.revision?`<div class="journal-label">核对后的修正</div><div class="journal-text">${esc(s.probe.revision)}</div>`:''}`:''}${s.evidence.length?`<details><summary>证据夹 · ${s.evidence.length} 条</summary>${evidenceShelfFor(s)}</details>`:''}${s.notes?`<div class="journal-label">随手记</div><div class="journal-text">${esc(s.notes)}</div>`:''}</article>`}).join('')}${t.title?`<article class="journal-card"><div class="micro">独立阅读挑战</div><h3>${esc(t.title)}</h3><div class="journal-text">${esc(t.conclusion||'还没有写下最后的判断。')}</div><button class="btn text" data-action="view" data-view="transfer">查看迁移自查</button></article>`:''}<p class="micro" style="margin-top:25px">导出包含你的预测、判断、随手记与迁移练习。自由回答未经过自动正确性评估。</p></div>`;}
const transferFields=[['title','论文名称','选择一篇你之前没读过的 AI / ML 论文。'],['url','原文链接（可选）','https://arxiv.org/abs/...'],['problem','它试图解决什么问题？','读 Introduction 后，用自己的话解释瓶颈。'],['hypothesis','在看 Method 前，我会怎么做？','记录预测和可能失败的条件。'],['contribution','哪些是真正新增的部分？','列出新组件与沿用部分，附章节位置。'],['evidence','最强的一条证据是什么？','写出表号、数据、对照、指标、预算和分母。'],['alternative','最值得怀疑的地方是什么？','提出一个替代解释与能排除它的最小实验。'],['conclusion','我的最终判断及边界','在……条件下，证据支持……尚不足以证明……']];
function transfer(){const t=state.transfer,phase=Math.max(0,Math.min(2,t.phase||0));let checks=[['scope','我的结论包含具体任务、协议与范围'],['baseline','我核对了 baseline 与计算预算'],['data','我区分了观测数据、推测与成功案例'],['uncertainty','我检查了不确定性和可能的数据污染'],['experiment','我提出了一个能改变判断的补充实验']];const fields=phase===0?transferFields.slice(0,4):phase===1?transferFields.slice(4,7):transferFields.slice(7);return `<div class="wide-page"><div class="page-top"><div><h1 class="page-title">独立阅读挑战</h1><p class="text-muted" style="margin:0;font-size:14px">换一篇没见过的论文，逐步撤掉辅助。</p></div><button class="btn" data-action="export">${icon('download',16)}导出记录</button></div><div class="transfer-banner">${icon('flag',25)}<p>这次不提供标准解读。打开你选的原文，先写预测，再读方法与实验。你能否独立找到证据与边界，才是这门课的检验。</p></div><section class="lesson"><div class="lesson-body"><div class="step-label">迁移练习 · 第 ${phase+1} / 3 步</div><h2>${['先找到问题，留下预测','回到方法与实验证据','形成自己的判断'][phase]}</h2>${phase>0?`<div class="prediction-replay"><div class="micro">你选择的论文</div><h3>${esc(t.title)}</h3><details><summary>回看最初的预测</summary><p>${esc(t.hypothesis)}</p></details></div>`:'<p class="micro">链接用于记录，不会自动解析论文。选择尚未读过的论文，自己打开原文。</p>'}${fields.map(([k,n,ph])=>`<label class="field-label" for="transfer-${k}">${n}</label>${['title','url'].includes(k)?`<input type="${k==='url'?'url':'text'}" id="transfer-${k}" data-transfer="${k}" value="${esc(t[k])}" placeholder="${ph}">`:`<textarea id="transfer-${k}" data-transfer="${k}" placeholder="${ph}">${esc(t[k])}</textarea>`}`).join('')}${phase===2?`<h3 class="subheading">用证据自评，不用完成量自评</h3>${checks.map(([k,n])=>`<label class="check-row"><input type="checkbox" data-transfer-check="${k}" ${t.checks?.[k]?'checked':''}>${n}</label>`).join('')}${t.submitted?`<div class="feedback"><strong>已保存这份独立判断。</strong><p>自查覆盖 ${checks.filter(([k])=>t.checks?.[k]).length} / 5 项。这是你报告的覆盖情况，不是客观能力分数。</p><p>下一步：请另一位读者只看你的证据链，指出一个最薄弱的推论；据此修改，再读第二篇陌生论文。</p></div>`:''}`:''}${phase>0?'<button class="btn text" data-action="transfer-back">回看上一步</button>':''}</div>${phase<2?footer('留下自己的回答，再继续读下一部分。',phase===0?'保存预测，去读方法与实验':'保存证据，形成判断','transfer-next',!transferPhaseReady()):footer('最后用证据检查结论的范围。','保存独立判断','save-transfer',!transferReady())}</section></div>`;}
function transferPhaseReady(){const t=state.transfer,phase=t.phase||0;if(phase===0)return !!t.title?.trim()&&['problem','hypothesis'].every(k=>(t[k]||'').trim().length>=12);return ['contribution','evidence','alternative'].every(k=>(t[k]||'').trim().length>=12);}

function transferReady(){const t=state.transfer;return !!t.title?.trim()&&['problem','hypothesis','contribution','evidence','alternative','conclusion'].every(k=>(t[k]||'').trim().length>=12);}
function render(scroll=false){const active=document.activeElement;const focusState=active?.id?{id:active.id}:active?.dataset?.action?{dataset:{...active.dataset}}:null;const openDetails=[...document.querySelectorAll('details[open]')].map(x=>x.className).filter(Boolean);$('#app').innerHTML=header()+(!storageOK?'<div class="storage-error">浏览器未能保存记录，请使用「判断手记」导出，避免丢失。</div>':'')+`<div class="layout">${sidebar()}<main class="workspace" id="main" tabindex="-1">${({course,compass,journal,transfer}[state.view]||course)()}</main></div>`;document.title=`${state.view==='course'?paper().short:state.view==='compass'?'阅读指南针':state.view==='journal'?'判断手记':'独立阅读挑战'} · 论文训练场`;if(state.view==='course'&&progress().step===4&&tab==='stats'){if(statsMode==='paired')updatePairedStats();else updateStats();}for(const name of openDetails){const detail=[...document.querySelectorAll('details')].find(x=>x.className===name);if(detail)detail.open=true;}if(!scroll&&focusState){const target=focusState.id?document.getElementById(focusState.id):[...document.querySelectorAll('[data-action]')].find(x=>Object.entries(focusState.dataset).every(([k,v])=>x.dataset[k]===v));if(target&&!target.disabled)target.focus({preventScroll:true});}if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}
function moveStep(n){const s=progress();s.step=Math.max(0,Math.min(6,n));s.unlocked=Math.max(s.unlocked,s.step);if(s.step===4&&!s.experimentSeen.includes('table'))s.experimentSeen.push('table');resetTransient();save();render(true);}
function openSource(page){const p=paper(),url=sourceUrl(p,page);const d=$('#source-dialog');d.innerHTML=`<div class="dialog-head"><span>${esc(p.short)} · 原文第 ${page} 页</span><div><a class="btn small" href="${url}" target="_blank" rel="noopener noreferrer">在新窗口打开 ${icon('external',12)}</a><button class="btn small" data-action="close-source" aria-label="关闭原文">${icon('close',16)}</button></div></div><div class="dialog-note">若浏览器不支持嵌入 PDF，请使用「在新窗口打开」。引用版本：${p.arxiv}。</div><iframe src="${url}" title="${esc(p.name)} 原始 PDF" loading="lazy"></iframe>`;d.showModal();}
function updateStats(){const n=statN,k=Math.round(statK/100*n),p=k/n,z=1.959963984540054,d=1+z*z/n,c=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;$('#stat-n-value').textContent=statN;$('#stat-k-value').textContent=`${(p*100).toFixed(1)}% (${k}/${n})`;$('#stat-result').innerHTML=`${((c-h)*100).toFixed(1)}% – ${((c+h)*100).toFixed(1)}% <span>Wilson 95% 区间</span>`;}
function exportNotes(){let lines=['# 论文训练场 · 判断手记','','导出时间：'+new Date().toISOString(),'本文件记录学习者自述，不是 AI 对自由回答的自动评分。',''];for(const p of PAPERS){const s=state.papers[p.id];if(!s)continue;lines.push(`## ${p.short} (${p.year})`,`原文：https://arxiv.org/abs/${p.arxiv}`,'',`### 最初的预测（把握 ${s.initialPrediction?.confidence??s.confidence??50}%）`,s.initialPrediction?.text||s.prediction||'尚未记录','');if(s.initialPrediction&&s.prediction!==s.initialPrediction.text)lines.push('### 之后修改的预测',s.prediction,'');if(s.reading?.answers){for(const[index,answer]of Object.entries(s.reading.answers)){if(!answer.note&&!answer.reviewed)continue;const q=LEARNING[p.id].passages[Number(index)];if(!q)continue;lines.push('### 原文标注 · '+q.section,q.quote,`PDF 第 ${q.page} 页`,answer.role===undefined?'尚未选择':READING_ROLES[answer.role],answer.note||'','');}}for(const [k,title]of [['introNote','我理解的贡献'],['methodNote','方法问题'],['ablationNote','消融判断'],['notes','随手记'],['revision','看法变化']])if(s[k])lines.push('### '+title,s[k],'');if(s.judgment)for(const [k,title]of [['claim','我的结论'],['evidence','证据'],['limit','保留意见']])if(s.judgment[k])lines.push('### '+title,s.judgment[k],'');if(s.evidence?.length){lines.push('### 证据夹','');for(const e of s.evidence)lines.push(e.text,e.reference,e.url,'');}if(s.probe?.submitted){const q=LEARNING[p.id].probe;lines.push('### 新情境首次判断',q.scenario,q.question,q.options[s.probe.first?.choice??s.probe.choice],`核对前把握：${s.probe.first?.confidence??50}%`,s.probe.first?.reason||s.probe.reason||'',`参考判断：${q.options[q.correct]}`,q.explain,s.probe.revision||'','');}lines.push(`完成自查：${s.done?'是':'否'}`,'');}if(state.transfer.title){lines.push('## 独立阅读挑战','');for(const[k,title]of transferFields)lines.push('### '+title,state.transfer[k]||'未填写','');lines.push('自查记录：'+JSON.stringify(state.transfer.checks||{}));}const blob=new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='paper-lab-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('判断手记已导出');}
function readingReady(s) {
  return LEARNING[paper().id].passages.every((_,i)=>s.reading.answers[i]?.reviewed);
}
function evidenceShelfFor(s) {return s.evidence.map(e=>`<div class="evidence-item"><p>${esc(e.text)}</p><a class="micro" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.reference)}</a></div>`).join('');}
function evidenceFor(kind,index) {
  const p=paper();
  if(kind==='passage') {
    const passage=LEARNING[p.id].passages[index];
    if(!passage)return null;
    return {id:`passage:${index}`,label:passage.section,page:passage.page,text:`“${passage.quote}”`,reference:`${p.short} · ${passage.section} · PDF 第 ${passage.page} 页 · ${p.arxiv}`,url:sourceUrl(p,passage.page)};
  }
  if(kind==='table') {
    const row=p.table.rows[index];
    if(!row)return null;
    return {id:`table:${index}`,label:row[0],page:p.table.page,text:row.map((v,i)=>`${p.table.headers[i]}：${v}`).join('；'),reference:`${p.short} · ${p.table.ref} · ${p.arxiv}`,url:sourceUrl(p,p.table.page)};
  }
  return null;
}
function pinButton(kind,index) {
  const id=`${kind}:${index}`,pinned=progress().evidence.some(e=>e.id===id);
  return `<button class="pin-button ${pinned?'pinned':''}" data-action="pin-evidence" data-kind="${kind}" data-index="${index}" aria-pressed="${pinned}" aria-label="${pinned?'移出':'收进'}证据夹">${icon(pinned?'check':'note',14)}${pinned?'已收集':'收进证据夹'}</button>`;
}
function evidenceShelf(forJudgment=false) {
  const s=progress();
  if(!s.evidence.length)return `<p class="micro">在原文或表格旁点「收进证据夹」，保留带出处的证据。</p>`;
  return `<div class="evidence-shelf">${s.evidence.map(e=>`<article class="evidence-item"><div class="evidence-item-head"><strong>${esc(e.label)}</strong><button class="btn text" data-action="source" data-page="${e.page}">第 ${e.page} 页 ${icon('external',12)}</button></div><p>${esc(e.text)}</p><div class="micro">${esc(e.reference)}</div>${forJudgment?`<button class="btn small secondary" data-action="cite-evidence" data-id="${esc(e.id)}">引用到我的证据回答</button>`:''}</article>`).join('')}</div>`;
}
function tableWithEvidence(p) {
  return `<div class="table-wrap"><table><thead><tr>${p.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}<th scope="col">证据</th></tr></thead><tbody>${p.table.rows.map((r,i)=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}<td>${pinButton('table',i)}</td></tr>`).join('')}</tbody></table></div>`;
}
function comparisonHTML(p) {
  if(p.id==='scaling')return '';
  const t=p.table,s=progress(),a=s.comparison?.a??0,b=s.comparison?.b??t.rows.length-1,col=s.comparison?.col??1;
  const base=Number(t.rows[a][col]),candidate=Number(t.rows[b][col]),delta=candidate-base;
  const unit=p.id==='attention'?'BLEU':'个百分点';
  const opts=(selected)=>t.rows.map((r,i)=>`<option value="${i}" ${selected===i?'selected':''}>${esc(r[0])}</option>`).join('');
  return `<details class="comparison-panel"><summary>亲手比较两行结果</summary><div class="comparison-controls"><label>对照<select data-compare="a">${opts(a)}</select></label><label>候选<select data-compare="b">${opts(b)}</select></label>${t.rows.every(r=>typeof r[2]==='number')?`<label>指标<select data-compare="col"><option value="1" ${col===1?'selected':''}>${t.headers[1]}</option><option value="2" ${col===2?'selected':''}>${t.headers[2]}</option></select></label>`:''}</div><div class="comparison-result">${delta>0?'+':''}${Number(delta.toFixed(2))} <span>${unit}</span></div><p>${a===b?'这是同一行，不能成为对照。':`相对变化为 ${base?((delta/base)*100).toFixed(1)+'%':'无法计算'}。分差只是描述；是否公平、是否能归因，还要检查预算与协议。`}</p></details>`;
}
function stage2(p,s) {
  const l=LEARNING[p.id],i=s.reading.current,passage=l.passages[i],answer=s.reading.answers[i]||{},count=l.passages.filter((_,idx)=>s.reading.answers[idx]?.reviewed).length;
  return `<div class="lesson-body"><div class="step-label">${icon('book',16)}第 3 步 / 先读，再标注</div><h2>这句话究竟在做什么？</h2><p class="body-copy">从原文里分清主张、结果与条件。一次只读一段，先判断，再看批注。</p><nav class="passage-nav" aria-label="原文片段">${l.passages.map((q,idx)=>`<button class="${i===idx?'active':''}" data-action="passage" data-index="${idx}" aria-current="${i===idx?'step':'false'}"><span>${s.reading.answers[idx]?.reviewed?icon('check',13):idx+1}</span>${esc(q.section)}</button>`).join('')}</nav><div class="quote-paper active-reading"><div class="quote-meta"><span>原文短摘录 · ${esc(passage.section)} · PDF 第 ${passage.page} 页</span>${pinButton('passage',i)}</div><blockquote>“${esc(passage.quote)}”</blockquote><div class="source-line"><span>${p.arxiv}</span>${sourceBtn(passage.page,'回到上下文')}</div></div><h3>它主要是在……</h3><div class="reading-roles" role="group" aria-label="原文句子的作用">${READING_ROLES.map((role,idx)=>`<button class="option ${answer.role===idx?'selected':''}" data-action="reading-role" data-index="${idx}" aria-pressed="${answer.role===idx}" ${answer.reviewed?'disabled':''}><span class="option-marker">${String.fromCharCode(65+idx)}</span>${role}</button>`).join('')}</div><label class="field-label" for="reading-note">哪个词或条件让你这样判断？</label><textarea id="reading-note" data-reading="note" placeholder="我注意到……它说明……">${esc(answer.note)}</textarea>${answer.reviewed?`<div class="feedback ${answer.role===passage.role?'':'wrong'}"><strong>${answer.role===passage.role?'你的标注与本课的读法一致。':'这里更适合读作：'+READING_ROLES[passage.role]}</strong><p>${passage.explanation}</p></div>`:`<div class="reading-actions"><button class="btn primary" data-action="review-reading" ${answer.role===undefined?'disabled':''}>核对我的标注</button><details><summary>需要一点提示</summary><p>${passage.hint}</p></details></div>`}${answer.reviewed&&i<l.passages.length-1?`<button class="btn secondary" data-action="passage" data-index="${i+1}" style="margin-top:18px">读下一段原文</button>`:''}${readingReady(s)?`<details class="reading-synthesis"><summary>把三段放回整篇论文</summary><div class="evidence-line"><span>主张</span><p>${p.claim}</p></div><div class="evidence-line"><span>证据</span><p>${p.evidence}</p></div><div class="evidence-line"><span>边界</span><p>${p.boundary}</p></div><p>${p.intro}</p></details>`:''}</div>${footer(`${count} / 3 段已核对。标注是阅读工具，不替代完整上下文。`,'进入方法拆解','next',!readingReady(s)&&s.unlocked<=2)}`;
}
function probeHTML(p,s) {
  const q=LEARNING[p.id].probe,r=s.probe;
  return `<section class="transfer-probe"><div class="step-label">${icon('flag',16)}换个新情境 · 教学虚构实验</div><h3>${q.title}</h3><p class="probe-scenario">${q.scenario}</p><h3>${q.question}</h3><div class="options" role="group" aria-label="迁移判断">${q.options.map((o,i)=>`<button class="option ${r.choice===i?'selected':''}" data-action="probe-choice" data-index="${i}" aria-pressed="${r.choice===i}" ${r.submitted?'disabled':''}><span class="option-marker">${String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join('')}</div><label class="field-label" for="probe-reason">写一句理由</label><textarea id="probe-reason" data-probe="reason" placeholder="我会这样判断，因为……" ${r.submitted?'readonly':''}>${esc(r.reason)}</textarea><label class="confidence" for="probe-confidence"><span>核对前的把握</span><input id="probe-confidence" data-probe="confidence" type="range" min="0" max="100" step="10" value="${r.confidence??50}" ${r.submitted?'disabled':''}><output id="probe-confidence-value">${r.confidence??50}%</output></label>${r.submitted?`<div class="feedback ${r.choice===q.correct?'':'wrong'}"><strong>${r.choice===q.correct?'这次判断有条件支持。':'这个新情境值得再检查。'}</strong><p>${q.explain}</p><p>${q.next}</p></div><label class="field-label" for="probe-revision">核对以后，我想修正或补充什么？</label><textarea id="probe-revision" data-probe="revision" placeholder="我的判断需要补上……">${esc(r.revision)}</textarea><p class="micro">保留首次选择与当时把握，方便回看。选择题有参考判断；你的理由与修正不自动评分。</p>`:`<button class="btn primary" data-action="submit-probe" ${!probeReady(s)?'disabled':''}>保存首次判断，核对理由</button>`}</section>`;
}
function probeReady(s) {
  return Number.isInteger(s.probe.choice)&&(s.probe.reason||'').trim().length>=8;
}
function stage6(p,s) {
  const i=PAPERS.findIndex(x=>x.id===p.id),next=PAPERS[i+1];
  return `<div class="lesson-body"><div class="step-label">第 7 步 / 看看能否带到下一篇</div><h2>换一个情境，你还会这样判断吗？</h2><p class="body-copy">先做一题新情境，再回看你留下的证据链。完成选择不代表已经掌握，理由和下一次独立阅读更重要。</p>${probeHTML(p,s)}${s.probe.submitted||s.done?`<div class="callout purple">${p.transfer}</div><h3>最后检查自己的结论</h3>${[['supported','我的结论写明了任务、对照与条件'],['traceable','我的关键判断能回到具体表格或段落'],['uncertain','我保留了至少一个未被排除的解释']].map(([k,n])=>`<label class="check-row"><input type="checkbox" data-review="${k}" ${s.review?.[k]?'checked':''}>${n}</label>`).join('')}${next?`<div class="next-preview"><div class="micro">接下来 · ${next.year}</div><strong>${next.short}</strong><span class="micro">下一种阅读能力：${next.skill}</span></div>`:''}`:''}${s.done?`<div class="saved-badge">${icon('check',14)}本篇判断已收入手记</div>`:''}</div>${footer('首次判断与修正会一同保留。',next?'完成本篇，进入下一篇':'完成本篇，挑战陌生论文','complete',(!s.probe.submitted&&!s.done)||!['supported','traceable','uncertain'].every(k=>s.review?.[k]))}`;
}
function pairedStatsHTML() {
  return `<div class="stat-lab"><div class="micro">独立教学模拟 · 不是任何论文的实验结果</div><h3>相同准确率，检验结果却可能不同</h3><p class="body-copy">同一批 100 题，A 答对 70 题，B 答对 80 题。调整两者同时答对的题数，观察逐题配对关系的影响。</p><label class="row" for="paired-overlap"><span>两者都答对</span><input id="paired-overlap" type="range" min="50" max="70" step="1" value="${pairedOverlap}"><output id="paired-overlap-value">${pairedOverlap}</output></label><div id="paired-matrix"></div><div id="paired-result" class="stat-result"></div><p class="micro">双侧精确 McNemar 检验：只用两者结果不同的题目。假设题目配对且各题独立；不处理训练种子、反复挑选或多重比较。p 值不是“假设正确的概率”。</p></div><div class="callout purple">准确率分差一直是 10 个百分点，但缺少逐题结果时，你无法恢复这个配对检验。效应大小、统计不确定性和实际价值应分别报告。</div>`;
}
function updatePairedStats() {
  const x=pairedOverlap,a=70-x,b=80-x,n=a+b,k=Math.min(a,b);
  let term=2**(-n),sum=term;
  for(let i=1;i<=k;i++){term*=((n-i+1)/i);sum+=term;}
  const value=Math.min(1,2*sum);
  $('#paired-overlap-value').textContent=x;
  $('#paired-matrix').innerHTML=tableHTML(['A / B','B 正确','B 错误'],[['A 正确',x,a],['A 错误',b,x-50]]);
  $('#paired-result').innerHTML=`p = ${value.toFixed(4)} <span>分差固定为 +10 个百分点</span>`;
}
function statsHTML() {
  return `<h2>分数更高，证据有多稳？</h2><p class="body-copy">先问随机性来自题目、训练种子，还是重复生成。同一批题目的结果，要保留配对关系。</p><div class="chip-tabs" aria-label="统计练习"><button data-action="stats-mode" data-mode="interval" class="${statsMode==='interval'?'active':''}">样本量与区间</button><button data-action="stats-mode" data-mode="paired" class="${statsMode==='paired'?'active':''}">同题配对比较</button></div>${statsMode==='paired'?pairedStatsHTML():`<div class="stat-lab"><div class="micro">独立教学模拟 · 非任何论文的实验结果</div><h3>相同成功率，样本量如何影响不确定性？</h3><label class="row" for="stat-n"><span>独立题目数</span><input id="stat-n" type="range" min="20" max="1000" step="10" value="${statN}"><output id="stat-n-value">${statN}</output></label><label class="row" for="stat-k"><span>成功率</span><input id="stat-k" type="range" min="5" max="95" step="5" value="${statK}"><output id="stat-k-value">${statK}%</output></label><div id="stat-result"></div><p class="micro">Wilson 95% 区间，假设独立同分布二项试验。重复抽样并按此程序构造区间，长期约 95% 覆盖真实比例。不估计模型差值，也不把同题多次生成当成新增独立题目。</p></div>`}<details><summary>回到原论文，该索取什么？</summary><p>逐题配对结果、多个随机种子、重采样单位和区间方法。置信区间是否重叠不能直接替代合适的差异检验；BLEU 等聚合指标也不能直接套用二元正确率检验。</p></details>`;
}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,s=progress(),p=paper();switch(a){
case'passage':s.reading.current=Math.max(0,Math.min(2,+b.dataset.index));save();render();break;
case'reading-role':{const i=s.reading.current;const answer=s.reading.answers[i]||(s.reading.answers[i]={});if(answer.reviewed)return;answer.role=+b.dataset.index;save();render();break;}
case'review-reading':{const i=s.reading.current,answer=s.reading.answers[i];if(!Number.isInteger(answer?.role))return;answer.reviewed=true;save();render();break;}
case'pin-evidence':{const ev=evidenceFor(b.dataset.kind,+b.dataset.index);if(!ev)return;const at=s.evidence.findIndex(x=>x.id===ev.id);if(at>=0)s.evidence.splice(at,1);else s.evidence.push(ev);save();render();toast(at>=0?'已移出证据夹':'已收集证据与原文出处');break;}
case'cite-evidence':{const ev=s.evidence.find(x=>x.id===b.dataset.id);if(!ev)return;const citation=ev.text+' — '+ev.reference;if(!(s.judgment.evidence||'').includes(citation))s.judgment.evidence=(s.judgment.evidence?s.judgment.evidence+'\n\n':'')+citation;save();render();$('#judgment-evidence')?.focus();break;}
case'probe-choice':if(s.probe.submitted)return;s.probe.choice=+b.dataset.index;save();render();break;
case'submit-probe':if(!probeReady(s))return;s.probe.submitted=true;s.probe.first={choice:s.probe.choice,confidence:s.probe.confidence??50,reason:s.probe.reason};save();render();break;
case'stats-mode':statsMode=b.dataset.mode;render();break;
case'menu':menu=!menu;render();break;case'view':state.view=b.dataset.view;menu=false;save();render(true);break;case'paper':state.current=b.dataset.id;state.view='course';menu=false;resetTransient();save();render(true);break;case'step':if(+b.dataset.step<=s.unlocked){s.step=+b.dataset.step;resetTransient();save();render(true);}break;case'next':if(s.step===2&&!readingReady(s)&&s.unlocked<=2)return;if(s.step===4&&(s.quiz!==p.table.correct||s.experimentSeen.length<4))return;moveStep(s.step+1);break;case'predict-option':s.choice=+b.dataset.index;save();render();break;case'save-prediction':if(s.choice===null||s.prediction.trim().length<12)return;s.predictionSaved=true;if(!s.initialPrediction)s.initialPrediction={text:s.prediction,confidence:s.confidence};moveStep(2);toast('预测已保存，现在开始对照原文');break;case'readtab':readTab=b.dataset.tab;render();break;case'annotation':annotation=!annotation;render();break;case'method-reveal':methodReveal=!methodReveal;render();break;case'experiment-tab':tab=b.dataset.tab;if(!s.experimentSeen.includes(tab))s.experimentSeen.push(tab);save();render();break;case'quiz':s.quiz=+b.dataset.index;save();render();break;case'ablation-reveal':ablationReveal=!ablationReveal;render();break;case'scale':scaleLog=!scaleLog;render();break;case'save-judgment':if(!judgmentReady(s))return;if(s.judgmentSaved){moveStep(6);}else{s.judgmentSaved=true;save();render();toast('已保存，参考边界在下方揭示');setTimeout(()=>$('.lesson-body .subheading')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'}),50);}break;case'complete':if(!s.probe.submitted&&!s.done)return;if(!['supported','traceable','uncertain'].every(k=>s.review?.[k]))return;s.done=true;const i=PAPERS.indexOf(p);if(PAPERS[i+1]){state.current=PAPERS[i+1].id;resetTransient();}else state.view='transfer';save();render(true);toast('本篇判断已收入手记');break;case'source':openSource(+b.dataset.page||1);break;case'close-source':$('#source-dialog').close();break;case'export':exportNotes();break;case'transfer-next':if(!transferPhaseReady())return;state.transfer.phase=Math.min(2,(state.transfer.phase||0)+1);save();render(true);break;case'transfer-back':state.transfer.phase=Math.max(0,(state.transfer.phase||0)-1);save();render(true);break;case'save-transfer':if(!transferReady())return;state.transfer.submitted=true;save();render();toast('独立判断已保存');break;}});
document.addEventListener('input',e=>{const el=e.target,s=progress();
if(el.dataset.reading){const i=s.reading.current;s.reading.answers[i]=s.reading.answers[i]||{};s.reading.answers[i][el.dataset.reading]=el.value;save();}
if(el.dataset.probe){const k=el.dataset.probe;if(s.probe.submitted&&k!=='revision')return;s.probe[k]=el.type==='range'?+el.value:el.value;const out=$('#probe-confidence-value');if(k==='confidence'&&out)out.textContent=el.value+'%';const btn=$('[data-action="submit-probe"]');if(btn)btn.disabled=!probeReady(s);save();}
if(el.id==='paired-overlap'){pairedOverlap=+el.value;updatePairedStats();}
if(el.dataset.field){const k=el.dataset.field;s[k]=el.type==='range'?+el.value:el.value;if(k==='confidence')$('#confidence-value').textContent=el.value+'%';if(k==='prediction'){$('#prediction-count').textContent=el.value.trim().length+' 字';const b=$('[data-action="save-prediction"]');if(b)b.disabled=s.choice===null||el.value.trim().length<12;}save();}if(el.dataset.judgment){s.judgment[el.dataset.judgment]=el.value;const b=$('[data-action="save-judgment"]');if(b)b.disabled=!judgmentReady(s);save();}if(el.dataset.transfer){state.transfer[el.dataset.transfer]=el.value;const b=$('[data-action="save-transfer"]');if(b)b.disabled=!transferReady();const next=$('[data-action="transfer-next"]');if(next)next.disabled=!transferPhaseReady();save();}if(el.id==='stat-n'||el.id==='stat-k'){if(el.id==='stat-n')statN=+el.value;else statK=+el.value;updateStats();}});
document.addEventListener('change',e=>{const el=e.target,s=progress();if(el.dataset.compare){s.comparison=s.comparison||{};s.comparison[el.dataset.compare]=+el.value;save();render();const panel=$('.comparison-panel');if(panel)panel.open=true;}if(el.id==='chart-column'){chartCol=+el.value;render();}if(el.dataset.review){s.review=s.review||{};s.review[el.dataset.review]=el.checked;save();const b=$('[data-action="complete"]');b.disabled=(!s.probe.submitted&&!s.done)||!['supported','traceable','uncertain'].every(k=>s.review[k]);}if(el.dataset.transferCheck){state.transfer.checks=state.transfer.checks||{};state.transfer.checks[el.dataset.transferCheck]=el.checked;save();}});
$('#source-dialog').addEventListener('click',e=>{if(e.target===$('#source-dialog'))$('#source-dialog').close();});
render();
})();
